import * as T from './three.module.js';
export const ICE_BASIC={left:{name:'얼음탄',damage:7,cost:4,cooldown:.28,range:7,speed:13},right:{name:'얼음안개',damage:2,cost:7,cooldown:.65,range:2.6,life:1.2,interval:.2}};
export class IceBasic{
 constructor(api){this.a=api;this.effects=[];}
 cast(owner,dir,hand){const spec=ICE_BASIC[hand],side=hand==='left'?-1:1;const bone=owner.g?.userData.puppet?.lastPositions?.[hand==='left'?'LeftHand':'RightHand'];let origin=bone?.clone()||new T.Vector3(owner.x+dir.z*.32*side,1.1,owner.z-dir.x*.32*side);if(!this.a.clearPath(owner,origin))origin.set(owner.x,1.1,owner.z);const ring=new T.Mesh(new T.TorusGeometry(.28,.035,6,32),new T.MeshBasicMaterial({color:0x299bff,transparent:true,opacity:.95}));ring.position.copy(origin);ring.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),new T.Vector3(dir.x,0,dir.z));this.a.scene.add(ring);this.effects.push({type:'iceHandRing',mesh:ring,owner,hand,dir:dir.clone(),life:.5,max:.5});
 if(hand==='left'){const mesh=new T.Mesh(new T.OctahedronGeometry(.16,0),new T.MeshStandardMaterial({color:0x8edcff,emissive:0x1874bb,emissiveIntensity:.7,roughness:.2}));mesh.position.copy(origin);mesh.scale.set(.7,.7,2);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),dir);this.a.scene.add(mesh);this.effects.push({type:'shot',mesh,owner,dir:dir.clone(),speed:spec.speed,life:spec.range/spec.speed,damage:spec.damage});}
 else{const mesh=new T.Group();for(let j=0;j<18;j++){const a=(j/17-.5)*1.6,r=.5+(j%6)/5*2;const puff=new T.Mesh(new T.IcosahedronGeometry(.35,1),new T.MeshBasicMaterial({color:j%2?0xa4d7ff:0x55baff,transparent:true,opacity:.24,depthWrite:false}));puff.position.set(Math.sin(a)*r,.4+(j%3)*.25,Math.cos(a)*r);mesh.add(puff);}mesh.position.set(origin.x,0,origin.z);mesh.rotation.y=Math.atan2(dir.x,dir.z);this.a.scene.add(mesh);this.effects.push({type:'iceMist',mesh,owner,dir:dir.clone(),point:{x:origin.x,z:origin.z},life:spec.life,max:spec.life,tick:0});}}
 update(dt){for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.life-=dt;let done=e.life<=0;
 if(e.type==='iceHandRing'){const bone=e.owner.g?.userData.puppet?.lastPositions?.[e.hand==='left'?'LeftHand':'RightHand'];if(bone)e.mesh.position.copy(bone);e.mesh.material.opacity=Math.max(0,e.life/e.max);e.mesh.scale.setScalar(1+(1-e.life/e.max)*.3);}
 if(e.type==='shot'&&!done){const steps=Math.max(1,Math.ceil(e.speed*dt/.08));for(let j=0;j<steps&&!done;j++){const before=e.mesh.position.clone(),next=before.clone().addScaledVector(e.dir,e.speed*dt/steps);if(this.a.collides(next.x,next.z,.12)||!this.a.clearPath(before,next)){done=true;break;}e.mesh.position.copy(next);const target=this.a.targets(e.owner).find(t=>Math.hypot(t.x-next.x,t.z-next.z)<.55);if(target){if(this.a.hit(target,e.damage,e.dir,0,e.owner))target.slow=Math.max(target.slow||0,.6);done=true;}}}
 if(e.type==='iceMist'){e.tick-=dt;for(const [j,p] of e.mesh.children.entries()){p.material.opacity=.26*Math.min(1,e.life/.3);p.scale.setScalar(1+.12*Math.sin((e.max-e.life)*7+j));}if(!done&&e.tick<=0){e.tick+=.2;for(const t of this.a.targets(e.owner)){const dx=t.x-e.point.x,dz=t.z-e.point.z,d=Math.hypot(dx,dz);if(d>2.6||d>.01&&(dx*e.dir.x+dz*e.dir.z)/d<.65||!this.a.clearPath(e.point,t))continue;if(this.a.hit(t,2,e.dir,0,e.owner))t.slow=Math.max(t.slow||0,.5);}}}
 if(done){this.a.remove(e.mesh);this.effects.splice(i,1);}}}
 clear(){for(const e of this.effects)this.a.remove(e.mesh);this.effects=[];}
}
